import { readFileSync, writeFileSync } from "node:fs";

const changed = new Set();

function read(path) {
  return readFileSync(path, "utf8");
}

function write(path, content) {
  writeFileSync(path, content);
  changed.add(path);
}

function replaceIf(path, from, to) {
  let content = read(path);
  if (!content.includes(from)) return false;
  content = content.split(from).join(to);
  write(path, content);
  return true;
}

function replaceMany(path, pairs) {
  let content = read(path);
  const before = content;
  for (const [from, to] of pairs) content = content.split(from).join(to);
  if (content !== before) write(path, content);
}

function replaceSidebar(path) {
  let content = read(path);
  const markers = [
    "{/* Strategic Call-to-Action Sidebar */}",
    "{/* Dynamic Sidebar CTA */}",
    "{/* Sidebar CTA */}",
  ];
  let index = -1;
  for (const marker of markers) {
    index = content.indexOf(marker);
    if (index >= 0) break;
  }
  if (index < 0) return;
  const head = content.slice(0, index);
  let tail = content.slice(index);
  const pattern = /<h4 className="text-sm font-black text-\[#1A3668\] uppercase tracking-wide">[\s\S]*?<\/h4>\s*<p className="text-xs text-slate-600 leading-relaxed font-medium">[\s\S]*?<\/p>\s*<p className="text-xs text-slate-600 leading-relaxed font-medium">[\s\S]*?<\/p>/;
  if (!pattern.test(tail)) return;
  tail = tail.replace(pattern, `<h4 className="text-sm font-black text-[#1A3668] uppercase tracking-wide">\n              Review Before You Commit\n            </h4>\n            <p className="text-xs text-slate-600 leading-relaxed font-medium">\n              Use the article as a checklist for terms, documents, and questions to resolve before bidding, signing, or committing resources.\n            </p>\n            <p className="text-xs text-slate-600 leading-relaxed font-medium">\n              <strong className="text-[#1A3668]">SubPreCheck</strong> can surface the relevant language, organize evidence-grounded issues, and prepare a focused package for discussion with the prime and qualified counsel.\n            </p>`);
  write(path, head + tail);
}

